class Solution {
    public int search(int[] nums, int target) {
        int mark = 0;
        for(int i = 0;i<nums.length;i++){
            if(i>0 && nums[i-1]>nums[i]){
                mark = i-1;
            }
        }
        int res1 = biSearch(nums,0,mark,target);
        if(res1!=mark+1 && nums[res1]==target)
        return res1;
        int res2 = biSearch(nums,mark+1,nums.length-1,target);
        if(res2 !=nums.length && nums[res2]==target)
        return res2;
        return -1;
    }
    public int biSearch(int[]nums,int left,int right,int target){
        int L = left;
        int R = right;
        while(L<=R){
            int mid = L + (R-L)/2;
            if(nums[mid]<target)
            L = mid+1;
            else
            R = mid-1;
        }
        return L;
    }
}
